python3 - <<'E'
p='internal/ui/oci_resources/browser_flow.go'
s=open(p).read()
s=s.replace('''// defaultImageSearcher is what a browser opens with: Docker Hub anonymously,
// any other registry answers imagesearch.ErrUnsupported without a request
// (IS-03 adds the others). Tests replace it before opening the browser.
var defaultImageSearcher imagesearch.Searcher = imagesearch.ByRegistry(imagesearch.HubSearcher{}, nil)''','''// defaultImageSearcher is what a browser opens with: Docker Hub through its
// search API, any other registry through its catalog (/v2/_catalog), so a
// private registry no longer answers imagesearch.ErrUnsupported. Tests replace
// it before opening the browser.
var defaultImageSearcher imagesearch.Searcher = imagesearch.ByRegistry(imagesearch.HubSearcher{}, imagesearch.CatalogSearcher{})''')
open(p,'w').write(s)
p='internal/imagesearch/catalog_http_test.go'
s=open(p).read()
s=s.replace('first != "seen:" && first != want {','first != want {').replace('want none or %q','want %q')
open(p,'w').write(s)
E
